import { useDidUpdateEffect } from "../../hooks";
import { ChangeEventHandler, useEffect, useRef, useState } from "react";
import {
  ChangeHandler,
  FieldValues,
  useFormContext,
  UseFormGetValues,
} from "react-hook-form";
import { toast } from "react-toastify";
import {
  Container,
  DropdownCustomLabel,
  DropdownCustomLabelSelectStyles,
  ErrorMessage,
  FakeButton,
  FakeContainer,
  FileInput,
  InfoIcon,
  InputLabel,
  RequiredSpan,
  Slider,
  StyledInput,
  StyledTextArea,
  Toggle,
  ToggleContainer,
  TooltipContainer,
  TooltipContent,
  ValidateButton,
} from "./styles";
import Select from "./Select";
import DropdownCustomLabelSelect from "../Select";

export interface IBaseFormInputProps
  extends React.InputHTMLAttributes<HTMLInputElement> {
  title?: string;
  type?: string;
  toggleOptions?: [string, string];
  bool?: boolean;
  span?: number;
  paddingTop?: number;
  selectPlaceholder?: string;
  options?: {
    label: string;
    value: any;
  }[];
  tooltip?: string;
  defaultValue?: any;
  required?: boolean;
  zIndex?: number;
  precision?: number;
  customOnChange?: (e: any) => void;
  logoError?: string | null;
  handleScrollBottom?: () => void;
  onInputChange?: (e: any) => void;
  creatable?: boolean;
  dynamicInitialValue?: any;
  canBeNaN?: boolean;
  titleLess?: boolean;
  disableCustom?: boolean;
  selectFilter?: (e: any) => any;
}

export interface IFormInputProps extends IBaseFormInputProps {
  name: string;
  fileLabel?: string;
  setFileLabel?: React.Dispatch<React.SetStateAction<string>>;
}

export interface ICustomFormInputProps extends IBaseFormInputProps {
  onChange: ChangeEventHandler<any>;
  fileLabel?: string;
  setFileLabel?: React.Dispatch<React.SetStateAction<string>>;
}

export const customOptions = [
  { label: "Text", value: "text" },
  { label: "Number", value: "number" },
];

export const customDropdownOptions = [
  { label: "No", value: "no" },
  ...customOptions,
];

export const cleanEmptyValues = (
  obj: Record<string, any>
): Record<string, any> => {
  return Object.entries(obj)
    .filter(
      ([_key, value]) =>
        value !== "" &&
        value !== null &&
        value !== undefined &&
        !Number.isNaN(value)
    )
    .reduce((acc, [currKey, currValue]) => {
      return {
        ...acc,
        [currKey]: currValue,
      };
    }, {});
};

const FormInput: React.FC<IFormInputProps | ICustomFormInputProps> = ({
  name,
  title,
  type,
  toggleOptions,
  span,
  paddingTop,
  bool,
  selectPlaceholder,
  defaultChecked = true,
  defaultValue,
  tooltip,
  required,
  zIndex,
  min,
  max,
  customOnChange,
  onChange,
  onInputChange,
  creatable,
  precision = 8,
  logoError = null,
  handleScrollBottom,
  dynamicInitialValue,
  canBeNaN = false,
  titleLess = false,
  disableCustom = false,
  selectFilter,
  fileLabel,
  setFileLabel,
  ...rest
}) => {
  const areaRef = useRef<HTMLTextAreaElement | null>(null);
  const [isCustom, setIsCustom] = useState(
    type === "dropdown" ? customDropdownOptions[0] : customOptions[0]
  );
  const [dragging, setDragging] = useState(false);
  const {
    register,
    formState: { errors },
    watch,
    unregister,
    setValue,
    getValues,
  } = useFormContext();

  const fileInputRef = useRef<HTMLInputElement>(null);

  useDidUpdateEffect(() => {
    if (type === "dropdown") {
      setIsCustom(customDropdownOptions[0]);
    } else {
      setIsCustom(customOptions[0]);
    }
  }, [type]);

  let error = null;

  try {
    error = eval(`errors?.${name}`);
  } catch (e) {
    error = null;
  }

  useEffect(() => {
    name &&
      //allow dynamic initial value to be 0 but not undefined, null or ""
      (dynamicInitialValue || dynamicInitialValue === 0) &&
      setValue(name, dynamicInitialValue);
  }, [dynamicInitialValue]);

  const inputValue = name && watch(name);

  const registerProps =
    name &&
    (type !== "number" && isCustom.value !== "number"
      ? register(name, {
          required: {
            value: required || false,
            message: "This field is required",
          },
          onChange: customOnChange,
        })
      : register(name, {
          valueAsNumber: true,
          required: {
            value: required || false,
            message: "This field is required",
          },
          onChange: customOnChange,
          validate: (value: any) => {
            if (!canBeNaN && required && Number.isNaN(value)) {
              return "Only numbers allowed";
            }

            if (value < (min || 0)) {
              return `Minimum value is ${min || 0}`;
            }

            if (max && value > max) {
              return `Maximum value is ${max || 100}`;
            }

            if (precision !== undefined && value) {
              let parsedValue = value;

              // remove scientific notation
              if (String(value).includes("e")) {
                parsedValue = Number(value).toFixed(
                  Number(String(value).split("-")[1])
                );
              }
              const regex = new RegExp(
                `^-?[0-9]\\d*(\\.\\d{0,${precision}})?$`
              );

              if (!regex.test(parsedValue)) {
                return precision > 0
                  ? `Maximum ${precision} decimals allowed`
                  : "Only integer numbers allowed";
              }
            }

            return true;
          },
        }));

  useEffect(() => {
    return () => {
      name && unregister(name);
    };
  }, [name, unregister, isCustom]);

  const areaProps: any = {
    error: Boolean(error),
    logoWarning: logoError !== null ? true : false,
    value: rest.value,
    placeholder:
      type === "object" && !rest.placeholder
        ? `E.g. {
  "key1": "value1",
  "key2": "value2"
    }`
        : "",
  };

  let inputProps = {
    type,
    defaultValue,
    ...areaProps,
    ...registerProps,
    ...rest,
  };

  // Special handling for file inputs
  if (type === "file") {
    inputProps.onChange = ((e: React.ChangeEvent<HTMLInputElement>) => {
      // Check if files were selected
      const files = e.target.files;
      if (files && files.length > 0) {
        // Use the name of the first selected file
        const fileName = files[0].name;
        // Update the custom label using the provided setter function from props
        if (setFileLabel) {
          setFileLabel(fileName);
        }
      } else {
        // Reset to default label if no file is selected
        if (setFileLabel) {
          setFileLabel("No file chosen");
        }
      }

      // Call any original onChange handler passed as a prop to FormInput
      if (onChange) {
        onChange(e);
      }
    }) as ChangeHandler;
  } else if (onChange) {
    // For other input types, use the original onChange prop directly
    inputProps["onChange"] = onChange as ChangeHandler;
    areaProps["onChange"] = onChange as ChangeHandler;
  }

  const containerProps = {
    paddingTop,
    span,
    zIndex,
  };

  const selectProps = {
    title,
    selectPlaceholder,
    name: name || "",
    error: Boolean(error),
    value: inputValue,
    handleScrollBottom,
    onInputChange,
    creatable,
    selectFilter,
    ...rest,
  };

  const { ref, ...registerRest } = registerProps || {};

  const preventScroll = (e: any) => {
    e.target.blur();
  };

  (type === "number" || isCustom.value === "number") &&
    (inputProps = {
      ...inputProps,
      step: 1 / 10 ** (precision || 0),
      onWheel: preventScroll,
    });

  type === "file" &&
    (inputProps = {
      ...inputProps,
      onDrop: (e: any) => {
        e.preventDefault();
        e.stopPropagation();

        e.target.files = e.dataTransfer.files;
        onChange && onChange(e);
      },
    });

  const handleKey = (e: any) => {
    if (e.key === "Tab" && (type === "textarea" || type === "object")) {
      e.preventDefault();
      if (areaRef.current) {
        const start = e.target.selectionStart;
        const end = e.target.selectionEnd;

        areaRef.current.value =
          areaRef.current.value.substring(0, start) +
          "\t" +
          areaRef.current.value.substring(end);

        if (typeof areaRef.current.selectionStart === "number") {
          areaRef.current.selectionStart = start + 1;
        }
        if (typeof areaRef.current.selectionEnd === "number") {
          areaRef.current.selectionEnd = end + 1;
        }
      }
    }
  };

  const preventEvent = (event: any) => {
    event.preventDefault();
    event.stopPropagation();
  };

  const handleDragEnter = (event: any) => {
    preventEvent(event);

    setDragging(true);
  };

  const handleDragLeave = (event: any) => {
    preventEvent(event);

    setDragging(false);
  };

  return (
    <Container {...containerProps}>
      {type !== "hidden" && !titleLess && (
        <InputLabel disabled={inputProps.disabled}>
          <span>
            {title || name}
            {required && <RequiredSpan>(required)</RequiredSpan>}
          </span>
          {tooltip && (
            <TooltipContainer>
              <InfoIcon />
              <TooltipContent>
                <span>{tooltip}</span>
              </TooltipContent>
            </TooltipContainer>
          )}

          {(type === "dropdown" || type === "custom") && !disableCustom && (
            <DropdownCustomLabel>
              <span>
                {type === "dropdown" ? `Custom value?` : "Input Type"}
              </span>
              <DropdownCustomLabelSelect
                options={
                  type === "dropdown" ? customDropdownOptions : customOptions
                }
                value={isCustom}
                onChange={(e: any) => {
                  setIsCustom(e) as any;
                }}
                styles={DropdownCustomLabelSelectStyles}
                isSearchable={false}
              />
            </DropdownCustomLabel>
          )}
          {type === "object" && (
            <ValidateButton
              type="button"
              onClick={() => {
                if (areaRef.current) {
                  try {
                    areaRef.current.value = JSON.stringify(
                      JSON.parse(areaRef.current.value),
                      null,
                      2
                    );
                    toast.success("JSON validated successfully");
                  } catch (e) {
                    toast.error("Invalid JSON");
                    console.error(e);
                  }
                }
              }}
            >
              Validate JSON
            </ValidateButton>
          )}
        </InputLabel>
      )}
      {type === "checkbox" && toggleOptions && (
        <>
          <ToggleContainer disabled={inputProps.disabled}>
            {toggleOptions.length > 1 && toggleOptions[0]}
            <Toggle>
              <StyledInput
                {...inputProps}
                required={false}
                value={String(!!inputValue)}
              />
              <Slider active={String(!!inputValue)} />
            </Toggle>
            {toggleOptions.length > 1 && toggleOptions[1]}
          </ToggleContainer>
        </>
      )}
      {type === "dropdown" && isCustom.value === "no" && (
        <Select {...selectProps} />
      )}
      {(type === "textarea" || type === "object") && (
        <StyledTextArea
          onKeyDown={handleKey}
          {...areaProps}
          {...registerRest}
          ref={(e) => {
            ref && ref(e);
            areaRef.current = e;
          }}
        />
      )}
      {type === "file" && (
        <>
          {fileLabel && (
            <FakeContainer>
              <FakeButton
                type="button"
                onClick={() => fileInputRef.current?.click()}
              >
                {fileLabel}
              </FakeButton>
            </FakeContainer>
          )}
          <FileInput
            ref={fileInputRef}
            {...inputProps}
            onDragEnter={handleDragEnter}
            onDragLeave={handleDragLeave}
            onDragOver={preventEvent}
            onMouseLeave={() => setDragging(false)}
            Dragging={dragging}
            style={{ display: fileLabel ? "none" : "block" }} // Hide the original file input
          />
        </>
      )}
      {type === "hidden" && <StyledInput {...inputProps} />}
      {type !== "checkbox" &&
        (type !== "dropdown" || isCustom.value !== "no") &&
        type !== "textarea" &&
        type !== "object" &&
        type !== "file" &&
        type !== "hidden" && <StyledInput {...inputProps} />}

      {error && (
        <ErrorMessage
          style={{ color: "red", fontSize: "0.8rem" }}
          warning={title === "Logo"}
        >
          {error?.message}
        </ErrorMessage>
      )}
      {logoError && (
        <ErrorMessage warning={!!logoError}>{logoError}</ErrorMessage>
      )}
    </Container>
  );
};

export default FormInput;
