import { useContract } from "../../../contexts/contract";
import {
  ButtonContainer,
  SubmitContainer,
  Spinner,
} from "../styles";

const SubmitButton: React.FC = () => {
  const { txLoading, submitForms } =
    useContract();

  const handleSubmit = async (e: any) => {
    e.preventDefault();
    submitForms();
  };

  return (
    <SubmitContainer>
      <ButtonContainer
        submit={!txLoading}
        type="submit"
        disabled={txLoading}
        onClick={handleSubmit}
      >
        Create Transaction &nbsp; {txLoading && <Spinner />}
      </ButtonContainer>
    </SubmitContainer>
  );
};

export default SubmitButton;
