interface IError {
  message: string;
}

export interface IResponse {
  data: any;
  code: string;
  error: IError | string;
}

export interface IAssetPoolResponse extends IResponse {
  data: {
    pool: IAssetPool;
  };
}
export interface IAssetPoolsResponse extends IResponse {
  data: {
    pools: IAssetPool[];
  };
}

export const getSomeAssetsPool = async (
  assets: string
): Promise<IAssetPoolsResponse> => {
  const res = await api.get({
    route: `assets/pool/list?asset=${assets}`,
  });

  if (!res.error || res.error === "") {
    return res || [];
  }

  return res.error;
};

export const getAssetPool = async (
  assetId: string
): Promise<IAssetPoolResponse | null> => {
  if (!assetId) return null;
  return await api.get({
    route: `assets/pool/${assetId}`,
  });
};

export const getParsedAssetPool = async (
  assetId: string
): Promise<IAssetPool | null> => {
  const res = await getAssetPool(assetId);

  if (res && (!res.error || res.error === "")) {
    return res.data.pool;
  }
  return null;
};
