import api from "../../services/api";
import { getParsedAssetPool, IAssetPool } from "../../services/collection";
import { IContractOption, allContractOptions } from "../../utils/contracts";
import {
  IAccount,
  IAccountResponse,
  IAssetResponse,
  IAssetsResponse,
  ICollectionList,
} from "../../types/contracts";
import React, {
  createContext,
  useContext,
  useEffect,
  useRef,
  useState,
} from "react";
import { useFees } from "../fees";
import { useQuery } from "react-query";

export const BASE_TX_SIZE = 250;

export interface IFormsData {
  data: any;
  contractType: string;
  typeAssetTrigger: number | null;
  collection?: ICollectionList;
  proposalId: number | null;
  binaryOperations: string[];
  depositType: string | null;
  withdrawType: number | null;
  assetID: number;
  itoTriggerType: number | null;
  buyType: boolean;
  isNFT: boolean | undefined;
  metadata: string;
  selectedBucket: string;
}

export interface IFeesMsgs {
  totalFeesMsg: string;
  totalKappFeesMsg: string;
  totalBandwidthFeesMsg: string;
}

export interface IContractHistory {
  hash: string;
  contractAddress: string;
}

export interface ExtensionEnv {
  type?: string;
  senderAccount?: string;
  abi?: {
    name: string;
    buffer: string;
  };
  wasm?: {
    name: string;
    buffer: string;
  };
  history?: IContractHistory[];
}

export interface IContractContext {
  txLoading: boolean;
  showAdvancedOpts: boolean;
  txHash: string | null;
  txResult: string;
  operationFailed: boolean;
  deployedAddress: string;
  showPayload: React.MutableRefObject<boolean>;
  isMultisig: React.MutableRefObject<boolean>;
  signTxMultiSign: React.MutableRefObject<boolean>;
  payload: any;
  contractOptions: IContractOption[];
  kdaFee: React.MutableRefObject<ICollectionList>;
  permID: number;
  extensionEnv: ExtensionEnv;
  ignoreCheckAmount: React.MutableRefObject<boolean>;
  collection: any;
  collectionAssetId: string;
  metadata: string;
  kdaFeePoolIsFetching: boolean;
  vscode: any;
  setTxLoading: React.Dispatch<React.SetStateAction<boolean>>;
  setShowAdvancedOpts: React.Dispatch<React.SetStateAction<boolean>>;
  setTxHash: React.Dispatch<React.SetStateAction<string | null>>;
  setContractOptions: React.Dispatch<React.SetStateAction<IContractOption[]>>;
  setPayload: React.Dispatch<React.SetStateAction<any>>;
  setPermID: React.Dispatch<React.SetStateAction<number>>;
  getAssets: () => Promise<ICollectionList[]>;
  getKAssets: () => Promise<ICollectionList[] | undefined>;
  setCollection: React.Dispatch<React.SetStateAction<any>>;
  setCollectionAssetId: React.Dispatch<React.SetStateAction<string>>;
  setTxResult: React.Dispatch<React.SetStateAction<string>>;
  setOperationFailed: React.Dispatch<React.SetStateAction<boolean>>;
  setDeployedAddress: React.Dispatch<React.SetStateAction<string>>;
  setMetadata: React.Dispatch<React.SetStateAction<string>>;
  submitForms: () => Promise<void>;
}

export const Contract = createContext({} as IContractContext);
export const ContractProvider: React.FC<{ children: any }> = ({ children }) => {
  const [txLoading, setTxLoading] = useState<boolean>(false);
  const [txHash, setTxHash] = useState<string | null>(null);
  const [showAdvancedOpts, setShowAdvancedOpts] = useState(false);
  const [contractOptions, setContractOptions] =
    useState<IContractOption[]>(allContractOptions);
  const [payload, setPayload] = useState<any>({});
  const [collection, setCollection] = useState<any>({});
  const [collectionAssetId, setCollectionAssetId] = useState<string>("");
  const [metadata, setMetadata] = useState<string>("");
  const [kdaFeeAsset, setKdaFeeAsset] = useState<ICollectionList | null>(null);
  const [vscode, setVsCode] = useState<any>(null);

  const { data: kdaFeePool, isFetching: kdaFeePoolIsFetching } = useQuery({
    queryKey: ["kdaFeePool", kdaFeeAsset],
    queryFn: () => getParsedAssetPool(kdaFeeAsset?.assetId || ""),
    enabled: !!kdaFeeAsset && kdaFeeAsset?.assetId !== "KLV",
  });

  const showPayload = useRef(false);
  const isMultisig = useRef(false);
  const signTxMultiSign = useRef(false);
  const ignoreCheckAmount = useRef(false);
  const kdaFee = useRef<ICollectionList>({} as ICollectionList);
  const [permID, setPermID] = useState<number>(0);
  const { getKappFee, bandwidthFeeMultiplier } = useFees();
  const [extensionEnv, setExtensionEnv] = useState<ExtensionEnv>({});
  const [txResult, setTxResult] = useState<any>("");
  const [operationFailed, setOperationFailed] = useState<boolean>(false);
  const [deployedAddress, setDeployedAddress] = useState<string>("");

  //vscode receive
  useEffect(() => {
    const handleMessage = (event: any) => {
      const message = event?.data; // The JSON data our extension sent
      switch (message?.command) {
        case "setEnvironment":
          setExtensionEnv(message?.data);
          break;
        case "txResult":
          setTxResult(message?.data?.result);
          setOperationFailed(message?.data?.failed || false);
          setDeployedAddress(message?.data?.deployedAddress || "");

          if (message?.data?.history) {
            setExtensionEnv((prev) => ({
              ...prev,
              history: message?.data?.history,
            }));
          }

          setTxLoading(false);
          break;
        default:
          break;
      }
    };

    window.addEventListener("message", handleMessage);
    return () => window.removeEventListener("message", handleMessage);
  }, []);

  //vscode send
  useEffect(() => {
    // acquireVsCodeApi exists in the global scope inside the extension webview
    let vscode: any;
    // @ts-ignore
    if (typeof acquireVsCodeApi === "function") {
      // @ts-ignore
      vscode = acquireVsCodeApi();
    } else {
      // For testing purposes, when not inside vscode extension
      setExtensionEnv({
        type: "deploy",
        senderAccount:
          "klv17e8zzgn73h6ehe3c6q9vlt77kuxk5euddmhymy5uhv2rhv0dc0nqlfp0ap",
      });
      vscode = {
        postMessage: (message: any) => {},
      };
    }

    setVsCode(vscode);
    vscode.postMessage({ command: "webviewReady" });
  }, []);

  const walletAddress = extensionEnv?.senderAccount;

  const baseBandwidthFee = BASE_TX_SIZE * bandwidthFeeMultiplier;

  const totalKappFees = getKappFee("SmartContract");

  const totalBandwidthFees =
    metadata?.length * bandwidthFeeMultiplier + baseBandwidthFee;

  const totalFees = totalKappFees + totalBandwidthFees;

  const getFeesInKDA = (fee: number, kdaFeePool: IAssetPool): number => {
    const KDAPrecision = kdaFeeAsset?.precision || 0;
    const feesWithRatio = (fee * kdaFeePool.fRatioKDA) / kdaFeePool.fRatioKLV;
    const feesWithoutKLVPrecision = feesWithRatio * 10 ** 6;
    const feesWithKDAPrecision = feesWithoutKLVPrecision / 10 ** KDAPrecision;
    return feesWithKDAPrecision;
  };

  const getEstimatedFees = () => {
    if (kdaFeeAsset && kdaFeePool) {
      return {
        totalFees: getFeesInKDA(totalFees, kdaFeePool),
        totalKappFees: getFeesInKDA(totalKappFees, kdaFeePool),
        totalBandwidthFees: getFeesInKDA(totalBandwidthFees, kdaFeePool),
        kda: kdaFeePool.kda,
        precision: kdaFeeAsset?.precision || 0,
      };
    } else {
      return {
        totalFees,
        totalKappFees,
        totalBandwidthFees,
        kda: "KLV",
        precision: 6,
      };
    }
  };

  const getKAssets = async () => {
    if (walletAddress === "") {
      return [] as ICollectionList[];
    }

    const response: IAssetsResponse = await api.get({
      route: `assets/list`,
      query: {
        owner: walletAddress,
        limit: 10000,
      },
    });
    if (response.error) return;

    const list: ICollectionList[] = [];

    if (response?.data?.assets?.length > 0) {
      response.data.assets.forEach((item) => {
        list.push({
          ...item,
          label: item.assetId,
          value: item.assetId,
          isNFT: item.assetType !== "Fungible",
        });
      });

      const kAssetsList = [...list];

      return kAssetsList;
    }
  };

  const getAssets = async () => {
    let account: IAccountResponse;
    if (walletAddress === "") {
      return [] as ICollectionList[];
    }
    if (extensionEnv?.senderAccount !== "") {
      account = await api.get({
        route: `address/${extensionEnv?.senderAccount}`,
      });
    } else {
      account = await api.get({
        route: `address/${walletAddress}`,
      });
    }

    if (
      !account?.data?.account?.assets &&
      account?.data?.account?.balance === (0 || undefined)
    ) {
      return [] as ICollectionList[];
    }

    const accountData: IAccount = account?.data?.account
      ? account.data.account
      : ({
          assets: [],
          frozenBalance: 0,
          balance: 0,
        } as unknown as IAccount);

    const { assets, frozenBalance, balance } = accountData;
    const list: ICollectionList[] = [];
    const assetInfo: IAssetsResponse = await api.get({
      route: `assets/list`,
      query: {
        asset: Object.keys(assets).join(","),
        limit: 10000,
      },
    });

    assetInfo.data?.assets?.forEach((item) => {
      const minEpochsToWithdraw = item?.staking?.minEpochsToWithdraw;

      list.push({
        ...assets[item.assetId],
        label: item.assetId,
        value: item.assetId,
        isNFT: assets?.[item.assetId]?.assetType === 1,
        minEpochsToWithdraw: minEpochsToWithdraw ? minEpochsToWithdraw : null,
        royalties: item.royalties || undefined,
      });
    });

    if (!Object.keys(assets).includes("KLV") && balance !== 0) {
      const assetInfo: IAssetResponse = await api.get({
        route: `assets/KLV`,
      });

      const minEpochsToWithdraw =
        assetInfo.data?.asset?.staking?.minEpochsToWithdraw;

      const royalties = assetInfo.data?.asset?.royalties;

      list.push({
        assetId: "KLV",
        label: "KLV",
        value: "KLV",
        precision: 6,
        isNFT: false,
        minEpochsToWithdraw: minEpochsToWithdraw ? minEpochsToWithdraw : null,
        balance,
        frozenBalance,
        royalties: royalties || undefined,
      });
    }
    list.sort((a, b) => (a.label > b.label ? 1 : -1));

    const KLV = list.splice(
      list.indexOf(
        list.find((item) => item.label === "KLV") as ICollectionList
      ),
      1
    );

    const KFI = list.splice(
      list.indexOf(
        list.find((item) => item.label === "KFI") as ICollectionList
      ),
      1
    );

    const assetsList = [...KLV, ...KFI, ...list];

    return assetsList || ([] as ICollectionList[]);
  };

  const submitForms = async () => {
    const allForms = document.querySelectorAll("form");
    allForms.forEach((form: HTMLFormElement) => {
      form.requestSubmit();
    });
  };

  const values: IContractContext = {
    txLoading,
    setTxLoading,
    txHash,
    setTxHash,
    txResult,
    setTxResult,
    operationFailed,
    setOperationFailed,
    deployedAddress,
    setDeployedAddress,
    showAdvancedOpts,
    setShowAdvancedOpts,
    getAssets,
    getKAssets,
    showPayload,
    isMultisig,
    signTxMultiSign,
    contractOptions,
    setContractOptions,
    payload,
    setPayload,
    kdaFee,
    permID,
    setPermID,
    extensionEnv,
    ignoreCheckAmount,
    collection,
    collectionAssetId,
    metadata,
    setCollection,
    setCollectionAssetId,
    setMetadata,
    kdaFeePoolIsFetching,
    submitForms,
    vscode,
  };
  return <Contract.Provider value={values}>{children}</Contract.Provider>;
};
export const useContract = (): IContractContext => useContext(Contract);
