import {
  DeployedAddressTextArea,
  InfoIcon,
  StyledTextArea,
  TooltipContainer,
  TooltipContent,
} from "../../FormInput/styles";
import { useContract } from "../../../contexts/contract";
import { useState } from "react";
import { AdvancedOptsContainer, ArrowDownIcon, ArrowUpIcon } from "../styles";
import { ExtraOptionContainer, FieldContainer, InputLabel } from "./styles";

const AdvancedOptionsContent: React.FC = () => {
  const { txResult, operationFailed, deployedAddress } = useContract();
  const tooltip = `Show the result of the last transaction`;

  return (
    <ExtraOptionContainer>
      {deployedAddress && deployedAddress.length > 0 && (
        <FieldContainer>
          <InputLabel>
            <span>Deployed Contract Address</span>
          </InputLabel>
          <DeployedAddressTextArea value={deployedAddress} readOnly/>
        </FieldContainer>
      )}
      <FieldContainer>
        <InputLabel>
          <span>Result</span>
          <TooltipContainer>
            <InfoIcon />
            <TooltipContent>
              <span>{tooltip}</span>
            </TooltipContent>
          </TooltipContainer>
        </InputLabel>
        <StyledTextArea value={txResult} error={Boolean(operationFailed)} readOnly/>
      </FieldContainer>
    </ExtraOptionContainer>
  );
};

const Result: React.FC = () => {
  const [showResult, setShowResult] = useState(true);

  return (
    <>
      <AdvancedOptsContainer onClick={() => setShowResult(!showResult)}>
        <span>Transaction Result</span>
        {showResult ? <ArrowUpIcon /> : <ArrowDownIcon />}
      </AdvancedOptsContainer>

      {showResult ? <AdvancedOptionsContent /> : null}
    </>
  );
};

export default Result;
