interface IError {
  message: string;
}

export interface IResponse {
  data: any;
  code: string;
  error: IError | string;
}

export interface IAssetsResponse extends IResponse {
  data: {
    assets: IAsset[];
  };
}

export interface IAssetResponse extends IResponse {
  data: {
    asset: IAsset;
  };
}

export interface IAccountResponse extends IResponse {
  pagination: IPagination;
  data: { account: IAccount };
}

export interface IPagination {
  self: number;
  next: number;
  previous: number;
  perPage: number;
  totalPages: number;
  totalRecords: number;
}

export interface IAsset {
  assetType: string;
  assetId: string;
  name: string;
  ticker: string;
  ownerAddress: string;
  logo: string;
  uris:
    | {
        [key: string]: string;
      }
    | IUri[];
  precision: number;
  initialSupply: number;
  circulatingSupply: number;
  maxSupply: number;
  royalties: IRoyalties;
  mintedValue: number;
  issueDate: number;
  staking: IStaking;
  roles?: IRole[];
  burnedValue: number;
  properties: {
    canFreeze: boolean;
    canWipe: boolean;
    canPause: boolean;
    canMint: boolean;
    canBurn: boolean;
    canChangeOwner: boolean;
    canAddRoles: boolean;
  };
  attributes: {
    isPaused: boolean;
    isNFTMintStopped: boolean;
  };
  hidden: boolean;
  verified: boolean;
  metadata?: string;
  mime?: string;
}

export interface IUri {
  key: string;
  value: string;
}

export interface IUris {
  uris?: IUri[];
}

export interface IStaking {
  interestType: string;
  minEpochsToWithdraw: number;
  totalStaked: number;
  apr:
    | {
        timestamp: number;
        epoch: number;
        value: number;
      }[]
    | [];

  fpr: {
    totalAmount: number;
    totalStaked: number;
    TotalClaimed: number;
    epoch: number;
    kda: IKDAFPR[];
  }[];
  currentFPRAmount: number;
  minEpochsToClaim: number;
  minEpochsToUnstake: number;
}

export interface IKDAFPR {
  kda: string;
  totalAmount: number;
  totalClaimed: number;
  precision?: number;
}

export interface IRole {
  address: string;
  hasRoleMint: boolean;
  hasRoleSetITOPrices: boolean;
}

export interface IAccount {
  name?: string;
  address: string;
  nonce: number;
  balance: number;
  frozenBalance: number;
  blsPublicKey?: string;
  allowance?: number;
  assets: {
    [key: string]: IAccountAsset;
  };
  buckets?: [
    {
      [key: string]: IBucket;
    }
  ];
  collection?: INfts[];
  timestamp: number;
  permissions?: IPermissions[];
}

export interface IAccountAsset {
  address: string;
  assetId: string;
  assetType: number;
  balance: number;
  precision: number;
  frozenBalance: number;
  unfrozenBalance: number;
  lastClaim: {
    timestamp: number;
    epoch: number;
  };
  buckets?: IBucket[];
  owner?: boolean;
  staking?: {
    interestType: string;
  };
}

export interface IBucket {
  address?: string;
  id: string;
  stakeAt: number;
  stakedEpoch: number;
  unstakedEpoch: number;
  balance: number;
  delegation: string;
  availableEpoch: number | string;
}

export interface INfts {
  address: string;
  assetName: string;
  collection: string;
  assetId: string;
  nftNonce: number;
  mime?: string;
  metadata?: string;
}

export interface IPermissions {
  id: number;
  type: number;
  permissionName: string;
  Threshold: number;
  operations: string;
  signers: [
    {
      address: string;
      weight: number;
    }
  ];
}

export interface IStakingRewards {
  label: string;
  value: number;
  inputValue?: string;
}

export interface ICollectionList {
  label: string;
  value: string;
  assetId: string;
  isNFT: boolean;
  frozenBalance?: number;
  balance?: number;
  precision?: number;
  buckets?: any[];
  minEpochsToWithdraw?: number | null;
  ownerAddress?: string;
  properties?: IAssetProperties;
  attributes?: {
    isPaused: boolean;
    isNFTMintStopped: boolean;
  };
  royalties: IRoyalties | undefined;
}

interface IAssetProperties {
  canAddRoles: boolean;
  canFreeze: boolean;
  canWipe: boolean;
  canPause: boolean;
  canMint: boolean;
  canBurn: boolean;
  canChangeOwner: boolean;
}

export interface IRoyalties {
  address?: string;
  marketPercentage?: number;
  marketFixed?: number;
  transferFixed?: number;
  transferPercentage?: [
    {
      amount: number;
      percentage: number;
    }
  ];
  itoPercentage?: number;
  itoFixed?: number;
  splitRoyalties?: ISplitRoyalties[];
}

export interface ISplitRoyalties {
  address: string;
  percentITOFixed: number;
  percentITOPercentage: number;
  percentTransferPercentage: number;
}

export interface ICollectionIdListResponse extends IResponse {
  data: {
    collection: {
      address: string;
      assetId: string;
      collection: string;
      nftNonce: number;
      assetName: string;
      assetType: number;
      balance: number;
      precision: number;
      frozenBalance: number;
      unfrozenBalance: number;
      lastClaim: {
        timestamp: number;
        epoch: number;
      };
      buckets: IBucket[];
      stakingType: number;
    }[];
  };
}

interface EndpointInput {
  name: string;
  type: string; // Simplified, in reality, this could be more specific or an enum.
  multi_arg?: boolean;
}

interface Endpoint {
  name: string;
  mutability: "mutable" | "readonly";
  inputs: EndpointInput[];
  outputs: any[]; // Simplified, outputs could be more detailed based on specific needs.
  payableInTokens?: string[];
}

export interface IOffset {
  left?: number;
  right?: number;
  top?: number;
  bottom?: number;
}

export type Place = "top" | "right" | "bottom" | "left";

export interface ICustomStyles {
  offset?: IOffset;
  place?: Place;
  delayShow?: number;
}

export type ABIStruct = {
  type: string;
  fields?: ABIStructField[];
  variants?: ABIVariant[];
};
export type ABIStructField = {
  name: string;
  type: string;
};

type ABIVariant = {
  name: string;
  fields: ABIVariantField[];
};

type ABIVariantField = {
  name: string;
  discriminant: number;
};

type Constructor = {
  docs?: string[];
  payableInTokens?: string[];
  inputs: {
    name: string;
    type: string;
  }[];
  outputs: any[];
};

export interface ABI {
  name: string;
  constructor: Constructor;
  endpoints: Endpoint[];
  types: Map<string, ABIStruct>;
}

